for _ in range(int(input())):
	(n, k) = map(int, input().split())
	rows = set()
	cols = set()
	for i in range(k):
		(r, c) = map(int, input().split())
		rows.add(r)
		cols.add(c)
	res_rows = []
	res_cols = []
	for i in range(1, n + 1):
		if i not in rows:
			res_rows.append(i)
		if i not in cols:
			res_cols.append(i)
	print(min(len(res_rows), len(res_cols)), end=' ')
	for i in range(len(res_rows)):
		print(res_rows[i], res_cols[i], end=' ')
	print()
